def answer_for(question: str, section: str) -> str:
    for pattern, answer in KNOWLEDGE:
        if re.search(pattern, question, re.IGNORECASE):
            return answer
    return (f"For {section}, define the behavior clearly, explain when it is useful, and name its main trade-off. "
            "In production, handle failure cases explicitly and verify the choice with a focused example or measurement.")


def parse_bank() -> list[dict[str, str]]:
    phase = "Python"
    section = "Python"
    records = []
    for raw in SOURCE.read_text(encoding="utf-8").splitlines():
        line = raw.strip()
        if not line:
            continue
        if line.startswith("Phase "):
            phase = line
            continue
        match = re.match(r"^\d+\.\s+(.*)$", line)
        if not match:
            continue
        body = match.group(1)
        if body.endswith("?"):
            records.append({"technology": "Python", "phase": phase, "section": section,
                            "question": body, "answer": answer_for(body, section)})
        else:
            section = body
    return records


def seed_database() -> None:
    Base.metadata.create_all(bind=engine)
    with SessionLocal() as db:
        for record in parse_bank():
            found = db.scalar(select(Question.id).where(
                Question.technology == record["technology"],
                Question.section == record["section"], Question.question == record["question"]))
            if found is None:
                db.add(Question(**record))
        db.commit()
